	if (*name == '\0')
		return 0;

	if (strcasecmp("Finish", name) == 0)
		return GetUICommandType(NULL) + 1;

	if (strcasecmp("Highlight_on", name) == 0)
		return GetUICommandType(NULL) + 1;

