/* @socom-skeleton stub HandlePad__11CRadioStripFPC4CPadi */
bool CRadioStrip::HandlePad(const CPad *pad, int)
{
	/* 0x38aa70: LEFT selects the previous option, RIGHT and CROSS the next (wrapping), each
	 * (FALLING) then checks it, with the selection sound; true when taken */
	if (!CanHandleInput())
		return false;

	if (pad->m_state[(u8)PAD_BUTTON::PAD_LEFT] == KEY_FALLING)
	{
		if (m_selection == 0)
			m_selection = (s32)size() - 1;
		else
			m_selection--;
	}
	else if (pad->m_state[(u8)PAD_BUTTON::PAD_RIGHT] == KEY_FALLING || pad->m_state[(u8)PAD_BUTTON::PAD_CROSS] == KEY_FALLING)
	{
		if ((u32)m_selection < size() - 1)
			m_selection++;
		else
			m_selection = 0;
	}
	else
	{
		return false;
	}

	RadioShowSelection(this);
	PressActive();
	PlaySelectionSound();
	return true;
}

/* @socom-skeleton stub PressActive__11CRadioStripFv */
void CRadioStrip::PressActive()
{
	/* 0x38a880: every checked option but the selected one is unchecked (its ONUNCHECK
	 * runs), then the selected one is checked when it is not (its ONCHECK runs). The
	 * options are CCheckBox controls (not type-tested in the ELF) */
	s32 i = 0;

	for (C2Dlist::iterator it = begin(); it != end(); ++it, ++i)
	{
		CCheckBox* option = static_cast<CCheckBox*>(*it);

		if (option != NULL && option->m_checked && i != m_selection)
		{
			option->m_checked = false;
			RunOptionAnim(option->m_onUncheck);
		}
	}

	i = 0;

	for (C2Dlist::iterator it = begin(); it != end(); ++it, ++i)
	{
		CCheckBox* option = static_cast<CCheckBox*>(*it);

		if (option != NULL && !option->m_checked && i == m_selection)
		{
			option->m_checked = true;
			RunOptionAnim(option->m_onCheck);
		}
	}
}

/* @socom-skeleton stub Tick__11CRadioStripFf */
void CRadioStrip::Tick(float dT)
{
	/* 0x38a560: the first tick shows and checks the selection; then C2DButton::Tick
	 * (inline in the ELF: caption, image and the pressed time) */
	if (m_init)
	{
		RadioShowSelection(this);
		PressActive();
		m_init = false;
	}

	C2DButton::Tick(dT);
}

/* @socom-skeleton stub __dt__12CCycleButtonFv */
CCycleButton::~CCycleButton()
{
	/* 0x38a420: the options (each leaves the list first); then ~C2D (the list) and
	 * ~C2DButton */
	for (C2Dlist::iterator it = m_options.begin(); it != m_options.end();)
	{
		C2D* option = *it;
		it = m_options.erase(it);

		if (option != NULL)
			delete option;
	}
}

/* @socom-skeleton stub HandlePad__12CCycleButtonFPC4CPadi */
bool CCycleButton::HandlePad(const CPad *pad, int)
{
	/* 0x38a090: the shown option's BUTTON anim on its button (FALLING); LEFT / RIGHT
	 * (FALLING) cycle the options (wrapping) and run the new one's ONACTIVATE anim */
	if (!CanHandleInput())
		return false;

	C2Dlist::iterator it = m_options.begin();

	for (s32 i = 0; i < m_selection; i++)
		++it;

	CycleItem* option = static_cast<CycleItem*>(*it);

	if (option->m_action.Type == ActionItem::ACTION_TYPE_BUTTON && pad->m_state[option->m_action.PadButton] == KEY_FALLING)
	{
		CZAnim* anim = ZAnim.GetAnim(option->m_action.Animation, NULL);

		if (anim == NULL)
			return false;

		if (option->m_action.Argument != NULL)
			anim->ActivateArg(1, 8, option->m_action.Argument, 0);
		else
			anim->Activate(NULL);

		return true;
	}

	if (pad->m_state[(u8)PAD_BUTTON::PAD_LEFT] == KEY_FALLING)
	{
		if (--m_selection < 0)
			m_selection = (s32)m_options.size() - 1;
	}
	else if (pad->m_state[(u8)PAD_BUTTON::PAD_RIGHT] == KEY_FALLING)
	{
		if ((u32)++m_selection >= m_options.size())
			m_selection = 0;
	}
	else
	{
		return false;
	}

	it = m_options.begin();

	for (s32 i = 0; i < m_selection; i++)
		++it;

	option = static_cast<CycleItem*>(*it);

	if (option == NULL)
		return true;

	if (option->m_action.Event == ActionItem::ONACTIVATE)
	{
		CZAnim* anim = NULL;

		if (GetLocalAnims() != NULL)
			anim = GetLocalAnims()->Anim(option->m_action.Animation);

		if (anim == NULL)
			anim = ZAnim.GetAnim(option->m_action.Animation, NULL);

		if (anim != NULL)
		{
			if (option->m_action.Argument != NULL)
				anim->ActivateArg(1, 8, option->m_action.Argument, 0);
			else
				anim->Activate(NULL);
		}
	}

	return true;
}

