namespace {
/* port: no symbol - ParseZAnimCmd's state part, inline six times in the ELF (YES and NO:
 * ACTIVE, NORMAL, PRESSED): the state's IMAGE (an anim name; 255 none) and TEXT_COLOR (128
 * grey without one); PULSE, SCALE and TEXT_GLOW (RANGE, TIME) are read into a local
 * ButtonState and dropped. A missing state is image 255, colour 255 255 255. */
void PopUpParseState(_zrdr* button, const char* tag, u8& image, s32* color)
{
	_zrdr* state = zrdr_findtag(button, tag);

	if (state == NULL)
	{
		image = 255;
		color[0] = color[1] = color[2] = 255;
		return;
	}

	C2DButton::ButtonState local;
	char* name = zrdr_findstring(state, "IMAGE");
	local._TexName = name != NULL ? name : "";
	PNT3D text = { 128.0f, 128.0f, 128.0f };
	zrdr_findPNT3D(state, "TEXT_COLOR", &text);
	zrdr_findreal(state, "PULSE", &local._fPulseTime, 1);
	zrdr_findreal(state, "SCALE", &local._fScale, 1);

	if (_zrdr* glow = zrdr_findtag(state, "TEXT_GLOW"))
	{
		f32 range[2];
		local._bGlowy = true;
		zrdr_findreal(glow, "RANGE", range, 2);
		local._iGlowStart = range[0];
		local._iGlowEnd = range[1];
		zrdr_findreal(glow, "TIME", &local._fGlowTime, 1);
	}
	else
	{
		local._bGlowy = false;
	}

	color[0] = (s32)text.x;
	color[1] = (s32)text.y;
	color[2] = (s32)text.z;
	image = *local._TexName.c_str() != '\0' ? (u8)ZAnim.m_CurAnim->AddName(local._TexName.c_str()) : 255;
}

/* port: no symbol - the YES / NO part, inline twice */
void PopUpParseButton(_zrdr* yesno, const char* tag, _zui_popup_button& rec)
{
	_zrdr* button = zrdr_findtag(yesno, tag);

	if (button == NULL)
	{
		rec.image[2] = rec.image[1] = rec.image[0] = 255;
		rec.caption = 255;
		return;
	}

	PNT2D point = { 0.0f, 0.0f };
	zrdr_findPNT2D(button, "POS", &point);
	rec.pos[0] = (s32)point.x;
	rec.pos[1] = (s32)point.y;
	point.x = point.y = 0.0f;
	zrdr_findPNT2D(button, "TEXTOFFSET", &point);
	rec.text_offset[0] = (s32)point.x;
	rec.text_offset[1] = (s32)point.y;
	zrdr_findint(button, "WIDTH", &rec.size[0], 1);
	zrdr_findint(button, "HEIGHT", &rec.size[1], 1);
	char* caption = zrdr_findstring(button, "CAPTION");
	rec.caption = caption != NULL ? (u8)ZAnim.m_CurAnim->AddName(caption) : 255;
	PopUpParseState(button, "ACTIVE", rec.image[0], rec.text_color[0]);
	PopUpParseState(button, "NORMAL", rec.image[1], rec.text_color[1]);
	PopUpParseState(button, "PRESSED", rec.image[2], rec.text_color[2]);
}
}

C2DAnimCmdHdr * CPopUpDialog::ParseZAnimCmd(_zrdr *reader)
{
	/* 0x387c00: the POPUP node's command (208 bytes, timeless): POSITION, the CAPTION and
	 * BACKGROUND (anim names), HEIGHT, WIDTH, XOFFSET, YOFFSET, SCALE, COLOR (128 grey),
	 * CANCELLABLE, PROTECTED, and YESNO: its VALVE (made a type-2 valve now) and the YES / NO
	 * buttons. ELF quirks kept: the +0x34 byte is cleared and then tested (the YESNO part
	 * always runs); a missing CAPTION / BACKGROUND is name 0 (the first), not 255 */
	_zui_popup_cmd* cmd = (_zui_popup_cmd*)_calloc(1, sizeof(_zui_popup_cmd), "zui_2d.cpp", 3512);
	cmd->hdr.header.timeless = 1;
	cmd->hdr.header.data_size = sizeof(_zui_popup_cmd);
	PNT2D point = { 0.0f, 0.0f };
	zrdr_findPNT2D(reader, "POSITION", &point);
	cmd->position[0] = (s32)point.x;
	cmd->position[1] = (s32)point.y;

	if (char* caption = zrdr_findstring(reader, "CAPTION"))
		cmd->caption = (u8)ZAnim.m_CurAnim->AddName(caption);

	if (char* background = zrdr_findstring(reader, "BACKGROUND"))
		cmd->background = (u8)ZAnim.m_CurAnim->AddName(background);

	zrdr_findint(reader, "HEIGHT", &cmd->height, 1);
	zrdr_findint(reader, "WIDTH", &cmd->width, 1);
	zrdr_findint(reader, "XOFFSET", &cmd->xoffset, 1);
	zrdr_findint(reader, "YOFFSET", &cmd->yoffset, 1);
	zrdr_findreal(reader, "SCALE", &cmd->scale, 1);
	PNT3D color = { 128.0f, 128.0f, 128.0f };
	zrdr_findPNT3D(reader, "COLOR", &color);
	cmd->color[0] = (s32)color.x;
	cmd->color[1] = (s32)color.y;
	cmd->color[2] = (s32)color.z;
	cmd->unused34 = 0;
	cmd->cancellable = zrdr_findtag(reader, "CANCELLABLE") != NULL;
	cmd->protect = zrdr_findtag(reader, "PROTECTED") != NULL;

	if (cmd->unused34 != 0)
	{
		cmd->yesno = false;
		return &cmd->hdr;
	}

	_zrdr* yesno = zrdr_findtag(reader, "YESNO");

	if (yesno == NULL)
		return &cmd->hdr;

	cmd->yesno = true;

	if (char* valve = zrdr_findstring(yesno, "VALVE"))
	{
		cmd->valve = (u8)ZAnim.m_CurAnim->AddName(valve);
		CValve::Create(valve, 0, (VALVE_TYPE)2);
	}

	PopUpParseButton(yesno, "YES", cmd->yes);
	PopUpParseButton(yesno, "NO", cmd->no);
	return &cmd->hdr;
}


/* port: no symbol - TickZAnimCmd's button part, inline twice in the ELF (YES, then NO): the
 * caption, size, scale, position and text offset, then the ACTIVE, NORMAL and PRESSED states
 * (image, text colour, scale; no glow or pulse) */
static void PopUpSetButton(C2DButton& button, IPNT2D& pos, IPNT2D& textOffset, const _zui_popup_button& rec,
	f32 scale, CZAnim* anim, zdb::CTextureRelocMgr* reloc)
{
	char* caption = anim->GetName(rec.caption);
	button._szCaption = caption;

	if (caption != NULL)
	{
		button._strCaption.SetString(caption);
		button._strCaption.UpdatePos();
	}

	button._fWidth = (f32)rec.size[0];
	button._fHeight = (f32)rec.size[1];
	button._strCaption.m_scale = scale;
	pos.x = rec.pos[0];
	pos.y = rec.pos[1];
	textOffset.x = rec.text_offset[0];
	textOffset.y = rec.text_offset[1];
	button._iTextX = textOffset.x;
	button._iTextY = textOffset.y;

	C2DButton::ButtonState* states[3] = { &button._ActiveState, &button._NormalState, &button._PressedState };

	for (s32 i = 0; i < 3; i++)
	{
		CSaferStr name;
		name = anim->GetName(rec.image[i]);
		C2DButton::ButtonState& state = *states[i];
		state._Texture = PrepTexture(name.c_str(), reloc);
		state._iGlowStart = 0.0f;
		state._iGlowEnd = 0.0f;
		state._bGlowy = false;
		state._fPulseTime = 0.0f;
		state._fGlowTime = 0.0f;
		state._pntTextColor.x = (f32)rec.text_color[i][0];
		state._pntTextColor.y = (f32)rec.text_color[i][1];
		state._pntTextColor.z = (f32)rec.text_color[i][2];
		state._TexName = name.c_str();
		state._fScale = scale;
	}
}

/* @socom-skeleton stub TickZAnimCmd__12CPopUpDialogFP14_zanim_cmd_hdrPfPb */
bool CPopUpDialog::TickZAnimCmd(_zanim_cmd_hdr *header, float *, bool *)
{
	/* 0x387020: the pop-up's one command (any type) fills the dialog: the POPUP node moves to
	 * POSITION; the background image at WIDTH x HEIGHT, the caption as wrapped text inside the
	 * offsets; YESNO makes the valve and both buttons, YES active. Leaves the result as it is
	 * and reports the command handled. */
	const _zui_popup_cmd* cmd = reinterpret_cast<const _zui_popup_cmd*>(header);
	CZAnim* anim = ZAnim.m_CurAnim;

	if (cmd == NULL)
		return true;

	char* background = anim->GetName(cmd->background);
	char* caption = anim->GetName(cmd->caption);

	if (caption != NULL && strcmp(caption, "INPUT_STRING") == 0) /* port: the ELF strcmps NULL as is */
		caption = anim->m_arg_list->GetCharP(0);

	zdb::CNode* node = ZAnim.m_CurAnim->GetNode(cmd->hdr.node_ref_index, false);

	if (node != NULL && strcmp("POPUP", node->m_name) == 0)
		node->SetPosition((f32)cmd->position[0], (f32)cmd->position[1], 0.0f);

	m_width = cmd->width;
	m_height = cmd->height;
	m_xoffset = cmd->xoffset;
	m_yoffset = cmd->yoffset;
	m_cancellable = cmd->cancellable != 0;
	m_protected = cmd->protect != 0;

	if (m_valve != NULL)
		m_valve = NULL;

	if (cmd->yesno)
	{
		m_valve = CValve::Create(anim->GetName(cmd->valve), VALVE_TYPE::VTYPE_TEMP);
		m_selection = 1;
		PopUpSetButton(m_yes, m_yesPos, m_yesTextOffset, cmd->yes, cmd->scale, anim, m_reloc);
		PopUpSetButton(m_no, m_noPos, m_noTextOffset, cmd->no, cmd->scale, anim, m_reloc);
		m_yes.SetActive();
		m_no.SetNormal();
	}

	if (m_child != NULL)
	{
		delete m_child;
		m_child = NULL;
	}

	m_text.SetString(caption);
	m_text.m_scale = cmd->scale;
	m_text.m_width = (f32)(m_width - 2 * m_xoffset);
	m_text.Update();
	m_text.m_color.x = (f32)cmd->color[0];
	m_text.m_color.y = (f32)cmd->color[1];
	m_text.m_color.z = (f32)cmd->color[2];
	C2DBitmap::Load(0.0f, 0.0f, (f32)m_width, (f32)m_height, PrepTexture(background, m_reloc));
	return true;
}

/* @socom-skeleton stub GetZAnimCmdType__12CPopUpDialogFPCc */
int CPopUpDialog::GetZAnimCmdType(const char *name)
{
	/* 0x386f80: past the UI commands, Caption is 1 and Background 2 (no name: 1; an empty
	 * name: 0). ELF quirk kept: any other name gets GetUICommandType(NULL) (a0 is still the
	 * zero of the last branch's delay slot), not that name's type. */
	if (name == NULL)
		return GetUICommandType(NULL) + 1;

	if (*name == '\0')
		return 0;

	if (strcasecmp("Caption", name) == 0)
		return GetUICommandType(NULL) + 1;

	if (strcasecmp("Background", name) == 0)
		return GetUICommandType(NULL) + 2;

	return GetUICommandType(NULL);
}

/* @socom-skeleton stub Render__9C2DVisualFP7CMatrix */
void C2DVisual::Render(CMatrix *transform)
{
	/* 0x386ec0: under a translucent UI node the object's alpha follows the opacity stack
	 * (0.99 counts as opaque); then it draws with the node's matrix. */
	f32 opacity = thePipe.m_opacity_stack[thePipe.m_opacity_stack_index];

	if (opacity < 1.0f)
	{
		if (opacity == 0.99f)
			opacity = 1.0f;

		m_2d->SetTrans(128.0f * opacity);
	}

	m_2d->Draw(*transform, m_reloc);
}

